func (p *swJSONParser) str() ([]rune, error) {
	if err := p.expect('"'); err != nil {
		return nil, err
	}
	out := []rune{}
	for p.i < len(p.s) {
		c := p.s[p.i]
		p.i++
		if c == '"' {
			return out, nil
		}
		if c < 0x20 {
			return nil, swInvalid("control character in a string")
		}
		if c != '\\' {
			out = append(out, c)
			continue
		}
		if p.i >= len(p.s) {
			break
		}
		e := p.s[p.i]
		p.i++
		switch e {
		case '"', '\\', '/':
			out = append(out, e)
		case 'b':
			out = append(out, '\b')
		case 'f':
			out = append(out, '\f')
		case 'n':
			out = append(out, '\n')
		case 'r':
			out = append(out, '\r')
		case 't':
			out = append(out, '\t')
		case 'u':
			cp, err := p.hex4()
			if err != nil {
				return nil, err
			}
			if cp >= 0xDC00 && cp <= 0xDFFF {
				return nil, swInvalid("lone low surrogate")
			}
			if cp >= 0xD800 && cp <= 0xDBFF {
				if err := p.literal("\\u"); err != nil {
					return nil, err
				}
				low, err := p.hex4()
				if err != nil {
					return nil, err
				}
				if low < 0xDC00 || low > 0xDFFF {
					return nil, swInvalid("lone high surrogate")
				}
				cp = 0x10000 + ((cp - 0xD800) << 10) + (low - 0xDC00)
			}
			out = append(out, cp)
		default:
			return nil, swInvalid("bad escape")
		}
	}
	return nil, swInvalid("unterminated string")
}

