// swJSONText gives a number member's text: a JSON number, or a string
// holding one (as 64-bit integers, NaN and the infinities are written).
func swJSONText(v *swJSON) (string, error) {
	switch v.kind {
	case 'n':
		return v.number, nil
	case 's':
		return string(v.runes), nil
	}
	return "", swInvalid("not a number")
}

